  // ===== Taqdimot muharriri =====
  'Tahrirlab bo\'lmaydi': ['Невозможно редактировать', "Can't edit"],
  'Fayl tahrirlashga tayyorlanmoqda…': ['Файл готовится к редактированию…', 'Preparing the file for editing…'],
  "Slaydlardagi matn, rasmlar va reja olinmoqda. Odatda 5–20 soniya.": ['Извлекаются текст, изображения и план слайдов. Обычно 5–20 секунд.', 'Extracting slide text, images and outline. Usually 5–20 seconds.'],
  "📥 Fayldan tiklandi: matn va rasmlar olindi, dizayn quyidagi mavzulardan biriga o'tkazildi. Slaydlarni ko'zdan kechirib, keyin «Saqlash» ni bosing.": ['📥 Восстановлено из файла: текст и изображения извлечены, дизайн переведён на одну из тем ниже. Просмотрите слайды и нажмите «Сохранить».', '📥 Restored from file: text and images extracted, the design switched to one of the themes below. Review the slides, then tap “Save”.'],
  'Oldingi slayd': ['Предыдущий слайд', 'Previous slide'],
  'Keyingi slayd': ['Следующий слайд', 'Next slide'],
  '{n}-reja': ['План {n}', 'Outline {n}'],
  'Muqova': ['Обложка', 'Cover'],
  'Mundarija': ['Содержание', 'Contents'],
  "Mundarija reja nomlari va slaydlar sonidan avtomatik tuziladi — alohida tahrirlash shart emas.": ['Содержание строится автоматически из пунктов плана и числа слайдов — отдельно редактировать не нужно.', 'Contents are built automatically from outline items and slide count — no separate editing needed.'],
  "Rasm yoki video slaydning o'ng tomonida joylashadi.": ['Изображение или видео размещается справа на слайде.', 'An image or video sits on the right side of the slide.'],
  '🖼 Rasmni almashtirish': ['🖼 Заменить изображение', '🖼 Replace image'],
  '🎬 Videoni almashtirish': ['🎬 Заменить видео', '🎬 Replace video'],
  "🎬 Video qo'shish": ['🎬 Добавить видео', '🎬 Add video'],
  "Video: MP4 yoki MOV, 25 MB gacha. PowerPoint'da slayd ochilganda o'ynaydi.": ['Видео: MP4 или MOV, до 25 МБ. Воспроизводится при открытии слайда в PowerPoint.', 'Video: MP4 or MOV, up to 25 MB. Plays when the slide opens in PowerPoint.'],
  'Video {n} MB dan oshmasin. Qisqaroq video tanlang.': ['Видео не должно превышать {n} МБ. Выберите видео короче.', 'Video must not exceed {n} MB. Choose a shorter one.'],
  'Bu fayl video emas (MP4 yoki MOV tanlang).': ['Это не видео (выберите MP4 или MOV).', 'This is not a video (choose MP4 or MOV).'],
  'Bu fayl rasm emas.': ['Это не изображение.', 'This is not an image.'],
  'Taqdimot nomi': ['Название презентации', 'Presentation title'],
  'Kichik sarlavha': ['Подзаголовок', 'Subtitle'],
  'Masalan: Aliyev Vali, 10-«A» sinf': ['Например: Алиев Вали, 10 «А» класс', 'E.g. Vali Aliyev, grade 10 “A”'],
  'Muqova rasmi': ['Изображение обложки', 'Cover image'],
  'Reja bandlari': ['Пункты плана', 'Outline items'],
  'Reja nomlari mundarija va slaydlar tepasidagi belgida ham yangilanadi.': ['Названия пунктов обновятся и в содержании, и в метке над слайдами.', 'Outline names also update in the contents and the label above slides.'],
  "Band qo'shish": ['Добавить пункт', 'Add item'],
  "«{kind}» uchun kamida {n} ta band kerak — aks holda ro'yxat ko'rinishida saqlanadi.": ['Для «{kind}» нужно минимум {n} пункта — иначе сохранится как список.', '“{kind}” needs at least {n} items — otherwise it is saved as a list.'],
  'Iqtibos matni': ['Текст цитаты', 'Quote text'],
  'Kirish jumlasi (ixtiyoriy)': ['Вводная фраза (необязательно)', 'Intro sentence (optional)'],
  "Bandni o'chirish": ['Удалить пункт', 'Delete item'],
  'Rasm yoki video': ['Изображение или видео', 'Image or video'],
  'Slayd amallari': ['Действия со слайдом', 'Slide actions'],
  '{n} ta slayd': ['Слайдов: {n}', '{n} slides'],
